solution_2:
第一眼看这个题目：哎呀，好难啊。。。

蒟蒻不才，于是只好写一个状压DP才过。

很简单，因为只有 9 个 0 或 1 ，所以只要用 2 
9
 =512 个数字来对应状态，根据异或的变换规律进行变换就行了。这种方法是 O(512∗9) 的，比绝大多数题解要快。



#include "bits/stdc++.h"
using namespace std;

int a,x,f[512];
int h,t,q[513];
int upd[10]={0,416,464,200,308,186,89,38,23,11};

int main()
{
	for(int i=8;i>=0;i--)
		scanf("%d",&a),x+=a*(1<<i);
	memset(f,-1,sizeof(f));
	f[x]=0;
	q[++t]=x;
	while(h<t)
	{
		x=q[++h];
		for(int i=1;i<=9;i++)
			if(f[x^upd[i]]==-1)
				q[++t]=x^upd[i],f[x^upd[i]]=f[x]+1;
	}
	printf("%d",f[511]);
	return 0;
}
